with base as (select *, cast(duration_sec as string) duration_sec_num from web_events where event_time >= timestamp '2023-11-18 14:00:00' and page is not null), flagged as (select *, case when lag(event_time) over (partition by page order by event_time, id) is null or event_time > lag(event_time) over (partition by page order by event_time, id) + interval '90' day then 1 else 0 end as session_start_flag from base), sessions_web_events as (select *, sum(session_start_flag) over (partition by page order by event_time, id rows between unbounded preceding and current row) as session_no from flagged) select case when session_start_flag >= 1 then 'PREMIUM' else 'STANDARD' end as session_start_flag_tier, date_trunc('quarter', event_time) as quarter_start, percentile_approx(session_no, array(0.25, 0.5, 0.75)) as session_no_quartiles, round(sum(duration_sec) / nullif(count(case when event_type = 'add_to_cart' then 1 end), 0), 2) as duration_sec_per_add_to_cart, round(avg(duration_sec), 2) as avg_duration_sec, count(*) as row_count, count(*) filter (where page = '/cart') as cart_rows, count(*) as event_count from sessions_web_events group by case when session_start_flag >= 1 then 'PREMIUM' else 'STANDARD' end, date_trunc('quarter', event_time) order by duration_sec_per_add_to_cart desc
